c='''def count_overdue(adviser_id, advisers):
    count = 0
    for adviser in advisers:
        if adviser.id == adviser_id:
            for ticket in adviser.tickets:
                if ticket is not None and ticket.days > 30 and ticket.status == "open":
                    count += 1
    return count'''
add('14:d-iii',['B2.2.2','B2.3.2','B2.3.3','B2.3.4'],'Each adviser has id and tickets attributes. tickets is a list of Ticket objects or None. A ticket has days and status; it is overdue only when days>30 and status="open". Adviser IDs are unique. Construct count_overdue(adviser_id,advisers), returning0 if no adviser matches.','One solution:\n'+c,[(1,'Initializes and returns count.'),(1,'Finds matching adviser ID.'),(1,'Traverses that adviser’s tickets.'),(1,'Safely ignores None and tests days>30.'),(1,'Tests open status and increments only matching tickets.')],[41],status='B',code=c,test_code=c+'''\nfrom types import SimpleNamespace as O
p=O(id=7,tickets=[None,O(days=30,status='open'),O(days=31,status='closed'),O(days=31,status='open')])
assert count_overdue(7,[p])==1 and count_overdue(8,[p])==0''',check='Executed missing ID,None,age boundary and status combinations.')
